| order by CustomRows desc","size":0,"title":"Default vs custom rows per table (devices with custom on)","timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","showExportToExcel":true,"gridSettings":{"filter":true,"rowLimit":10000,"formatters":[{"columnMatch":"DefaultRows","formatter":4,"formatOptions":{"palette":"gray","min":0}},{"columnMatch":"CustomRows","formatter":4,"formatOptions":{"palette":"green","min":0}}]}},"customWidth":"50","name":"ov-delta-grid"},{"type":3,"content":{"version":"KqlItem/1.0","query":"union isfuzzy=true (DeviceCustomProcessEvents|extend T='Process'),(DeviceCustomNetworkEvents|extend T='Network'),(DeviceCustomFileEvents|extend T='File'),(DeviceCustomRegistryEvents|extend T='Registry'),(DeviceCustomImageLoadEvents|extend T='Image Load'),(DeviceCustomScriptEvents|extend T='Script')
| where Timestamp {TimeRange}
| where '{DeviceName}' in ('All Devices','*') or isempty('{DeviceName}') or DeviceName contains '{DeviceName}'
| summarize Events=count() by bin(Timestamp, 1h), T
| order by Timestamp asc","size":0,"title":"Custom collection volume over time by table","timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","visualization":"timechart","chartSettings":{"group":"T","createOtherGroup":0}},"customWidth":"50","name":"ov-trend"},{"type":1,"content":{"json":"**Tenant coverage and ingestion** - left grid shows which devices are streaming each custom table. Right chart shows total tenant ingestion in GB per day across every table (billable), so you can gauge whether the workspace tier or commitment tier needs to scale."},"name":"ov-matrix-header"},{"type":3,"content":{"version":"KqlItem/1.0","query":"union isfuzzy=true (DeviceCustomProcessEvents | extend Tbl='Process'), (DeviceCustomNetworkEvents | extend Tbl='Network'), (DeviceCustomFileEvents | extend Tbl='File'), (DeviceCustomRegistryEvents | extend Tbl='Registry'), (DeviceCustomImageLoadEvents | extend Tbl='Image Load'), (DeviceCustomScriptEvents | extend Tbl='Script')
