let c = toscalar(DeviceCustomProcessEvents | where Timestamp {TimeRange} | where '{DeviceName}' in ('All Devices','*') or isempty('{DeviceName}') or DeviceName contains '{DeviceName}' | count);
union (print label='Default on custom devices', value=w), (print label='With Custom', value=c)","size":3,"title":"Process event counts","timeContextFromParameter":"TimeRange","queryType":0,"resourceType":"microsoft.operationalinsights/workspaces","visualization":"tiles","tileSettings":{"showBorder":true,"titleContent":{"columnMatch":"label"},"leftContent":{"columnMatch":"value","formatter":12,"formatOptions":{"palette":"auto"},"numberFormat":{"unit":17,"options":{"style":"decimal","maximumFractionDigits":0}}}}},"customWidth":"100","name":"pr-tiles"},{"type":3,"content":{"version":"KqlItem/1.0","query":"let cd = DeviceCustomProcessEvents | where Timestamp {TimeRange} | distinct DeviceName;
